.knowledge-map>div:nth-child(2){background:linear-gradient(90deg,#e5d7c9 0 8px,#fffdf8 8px 100%)}
.knowledge-map>div:nth-child(3){background:linear-gradient(90deg,#d9e0df 0 8px,#fffdf8 8px 100%)}
