}

/* Article body resembles a printed reference page */
.article-layout{
  position:relative;
}
.article-layout:before{
  content:"";
  position:absolute;
  left:-28px;
  top:12px;
  bottom:24px;
  width:1px;
  background:linear-gradient(#c6b28c,rgba(198,178,140,.18));
}
.article h2{
  position:relative;
}
.article h2:before{
  content:"";
  position:absolute;
  left:-24px;
  top:.55em;
  width:11px;
  height:1px;
  background:#b79a68;
}
.article blockquote,
.inline-note{
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.45);
}

/* Tool cards: index-card tabs, still clearly utilities */
.calc{
  overflow:visible;
}
.calc:after{
  content:"";
  position:absolute;
  top:-1px;
  right:18px;
  width:34px;
  height:8px;
  border:1px solid #cdbfa8;
  border-bottom:0;
  border-radius:4px 4px 0 0;
