/* Technical terms are visibly interactive, but not loud. */
.term-help{
  appearance:none;
  -webkit-appearance:none;
  display:inline;
  position:relative;
  padding:0 1px;
  margin:0;
  border:0;
  border-bottom:1px dotted #88734f;
  background:transparent;
  color:#304e45;
  font:inherit;
  line-height:inherit;
  font-weight:600;
  cursor:help;
  text-decoration:none;
  text-underline-offset:3px;
}

.term-help:hover,
.term-help:focus-visible,
.term-help[aria-expanded="true"]{
  color:#6f5740;
  border-bottom-style:solid;
  background:rgba(179,151,103,.09);
  border-radius:2px;
  outline:none;
}

.term-help:focus-visible{
  box-shadow:0 0 0 2px rgba(168,141,97,.18);
}

/* Small marker makes it obvious that the word can be opened. */
.term-help:after{
  content:"?";
  display:inline-grid;
  place-items:center;
  width:12px;
  height:12px;
  margin-left:3px;
  transform:translateY(-1px);
  border:1px solid #b49b72;
  border-radius:50%;
  color:#806b4c;
  font:700 8px/1 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;
  vertical-align:middle;
  opacity:.78;
}

.term-tooltip{
  position:fixed;
  z-index:1000;
  width:min(330px,calc(100vw - 28px));
  padding:14px 15px 13px;
  background:#fffdf8;
  border:1px solid #d3c7b4;
  border-radius:7px;
  box-shadow:0 15px 38px rgba(42,38,31,.16);
  color:#353b37;
  opacity:0;
  transform:translateY(4px);
  pointer-events:none;
  transition:opacity .12s ease,transform .12s ease;
}

.term-tooltip.open{
  opacity:1;
  transform:translateY(0);
  pointer-events:auto;
}

.term-tooltip:before{
  content:"";
  position:absolute;
  width:9px;
  height:9px;
  background:#fffdf8;
  border-left:1px solid #d3c7b4;
  border-top:1px solid #d3c7b4;
  transform:rotate(45deg);
  top:-5px;
  left:22px;
}

.term-tooltip[data-side="top"]:before{
  top:auto;
  bottom:-5px;
  transform:rotate(225deg);
}

.term-tooltip .term-en{
  display:block;
  margin-bottom:4px;
  color:#765f42;
  font-size:11px;
  font-weight:700;
  letter-spacing:.04em;
}

.term-tooltip strong{
  display:block;
  margin-bottom:6px;
  color:#213e35;
  font:600 17px/1.25 Georgia,"Times New Roman",serif;
}

.term-tooltip p{
  margin:0;
  font-size:13px !important;
  line-height:1.55 !important;
  color:#59615c;
}

.term-tooltip .term-hint{
  display:block;
  margin-top:9px;
  padding-top:8px;
  border-top:1px solid #ebe4d8;
  color:#91918b;
  font-size:9.5px;
}

